describe('default of negated and positive option does not depend on order', () => {
  test('when negated then positive and no args then value is undefined', () => {
    const program = new commander.Command();
    program.option('--no-pepper').option('--pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBeUndefined();
  });

  test('when positive then negated and no args then value is undefined', () => {
    const program = new commander.Command();
    program.option('--pepper').option('--no-pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBeUndefined();
  });

  test('when lone negated and no args then value is true', () => {
    const program = new commander.Command();
    program.option('--no-pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe(true);
  });

  test('when positive then negated with default then default is used', () => {
    const program = new commander.Command();
    program.option('--pepper').option('--no-pepper', 'remove pepper', 'plain');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toEqual('plain');
  });

  test('when negated with default then positive then default is used', () => {
    const program = new commander.Command();
    program.option('--no-pepper', 'remove pepper', 'plain').option('--pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toEqual('plain');
  });
});

